1	/**
2	 * Тесты сборки счёта.
3	 *
4	 * Счёт без налогов: итог совпадает с подытогом, форма Invoice — {number, customer, lines,
5	 * subtotal, total}. Форма — контракт: её сверяют литералом, поэтому новые поля появляются
6	 * в Invoice только когда им есть что сказать.
7	 */
8	
9	import { deepStrictEqual, strictEqual } from 'node:assert/strict';
10	import { describe, it } from 'node:test';
11	
12	import { bill } from '../src/index.ts';
13	
14	const customer = { name: 'Иван', email: 'ivan@example.ru', phone: '+79001234567' };
15	
16	describe('сборка счёта', () => {
17	  it('итог совпадает с подытогом, пока налогов нет', () => {
18	    const inv = bill('СЧ-1', customer, [
19	      { title: 'Пакет', qty: 2, priceK: 333 },
20	      { title: 'Коробка', qty: 1, priceK: 334 },
21	    ]);
22	    strictEqual(inv.subtotal, 1_000);
23	    strictEqual(inv.total, 1_000);
24	  });
25	
26	  it('форма счёта — ровно пять полей', () => {
27	    const inv = bill('СЧ-2', customer, [{ title: 'Пакет', qty: 1, priceK: 100 }]);
28	    deepStrictEqual(Object.keys(inv).sort(), ['customer', 'lines', 'number', 'subtotal', 'total']);
29	    strictEqual(inv.number, 'СЧ-2');
30	  });
31	});
32

1	/**
2	 * Счёт.
3	 *
4	 * Сборка итогового документа из позиций. Порядок слагаемых значим и закреплён: подытог по
5	 * позициям, дальше — налоги и сборы, каждый отдельным полем, и только потом итог. Любое
6	 * новое слагаемое встаёт в этот порядок явно, а не «где получилось».
7	 */
8	
9	import type { BillingConfig } from './config.ts';
10	import { resolveConfig } from './config.ts';
11	import type { Customer } from './customer.ts';
12	import type { Kopeck } from './money.ts';
13	import { subtotal } from './lines.ts';
14	import type { Line } from './lines.ts';
15	
16	/** Выставленный счёт — так его показывают покупателю и так же проверяют в поддержке. */
17	export interface Invoice {
18	  /** Номер счёта, присваивает вызывающий. */
19	  number: string;
20	  customer: Customer;
21	  lines: readonly Line[];
22	  /** Подытог по позициям, до налогов. */
23	  subtotal: Kopeck;
24	  /** Сумма к оплате. Сейчас совпадает с подытогом: налогов в расчёте пока нет. */
25	  total: Kopeck;
26	}
27	
28	/** Собрать счёт из позиций. */
29	export function buildInvoice(
30	  number: string,
31	  customer: Customer,
32	  lines: readonly Line[],
33	  config?: Partial<BillingConfig>,
34	): Invoice {
35	  resolveConfig(config); // конфиг читается здесь одним местом — переопределения действуют везде
36	  const sub = subtotal(lines);
37	  return { number, customer, lines, subtotal: sub, total: sub };
38	}
39

1	/**
2	 * Деньги.
3	 *
4	 * Всё внутри считается в КОПЕЙКАХ целым числом. Рубли с плавающей точкой в расчёте счёта
5	 * не появляются нигде: 0.1 + 0.2 в двоичной дроби не равно 0.3, и на цепочке
6	 * «позиции → подытог → налог» это вылезает расхождением в копейку.
7	 */
8	
9	/** Целое число копеек. */
10	export type Kopeck = number;
11	
12	/** Рубли (может быть дробным) → копейки. */
13	export function rub(amount: number): Kopeck {
14	  return Math.round(amount * 100);
15	}
16	
17	/** Сумма нескольких величин. */
18	export function add(...parts: Kopeck[]): Kopeck {
19	  let total = 0;
20	  for (const p of parts) total += p;
21	  return total;
22	}
23	
24	/** Разность, не уходящая ниже нуля: скидка не может сделать счёт платным наоборот. */
25	export function subtract(amount: Kopeck, taken: Kopeck): Kopeck {
26	  const left = amount - taken;
27	  return left < 0 ? 0 : left;
28	}
29	
30	/**
31	 * Процент от суммы с округлением ПОЛОВИНЫ ВВЕРХ.
32	 *
33	 * Правило округления у нас одно на весь расчёт. Отбрасывание (Math.floor без поправки)
34	 * или свой round в соседнем модуле — это расхождение в копейку на каждой второй строке
35	 * счёта: 10.5 копейки налога — это 11, а не 10.
36	 */
37	export function percent(amount: Kopeck, pct: number): Kopeck {
38	  return Math.floor((amount * pct) / 100 + 0.5);
39	}
40	
41	/** «1 234,56 ₽» — пробел между разрядами, запятая перед копейками. */
42	export function formatRub(amount: Kopeck): string {
43	  const sign = amount < 0 ? '-' : '';
44	  const abs = Math.abs(amount);
45	  const whole = Math.floor(abs / 100);
46	  const cents = abs % 100;
47	  const groups = String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
48	  return `${sign}${groups},${String(cents).padStart(2, '0')} ₽`;
49	}
50

