1	/**
2	 * Конфигурация биллинга.
3	 *
4	 * Всё, что меняется между площадками, живёт здесь, а не размазано по коду. Читается через
5	 * resolveConfig: прямое обращение к DEFAULT_CONFIG из модулей запрещено — иначе переопределение
6	 * конфига молча перестаёт действовать на половину мест.
7	 */
8	
9	export interface BillingConfig {
10	  /** Валюта счетов. Других у нас нет, но поле есть: отчётность её читает. */
11	  currency: 'RUB';
12	}
13	
14	export const DEFAULT_CONFIG: BillingConfig = {
15	  currency: 'RUB',
16	};
17	
18	/** Конфиг с переопределениями площадки. Не указанное — из DEFAULT_CONFIG. */
19	export function resolveConfig(partial?: Partial<BillingConfig>): BillingConfig {
20	  return { ...DEFAULT_CONFIG, ...partial };
21	}
22

1	/**
2	 * Тесты денег: правила округления и арифметики — единственное место, где они зафиксированы.
3	 */
4	
5	import { strictEqual } from 'node:assert/strict';
6	import { describe, it } from 'node:test';
7	
8	import { add, formatRub, percent, rub, subtract } from '../src/index.ts';
9	
10	describe('деньги', () => {
11	  it('рубли переводятся в копейки', () => {
12	    strictEqual(rub(249), 24_900);
13	    strictEqual(rub(0.5), 50);
14	  });
15	
16	  it('сумма и разность', () => {
17	    strictEqual(add(100, 250, 50), 400);
18	    strictEqual(subtract(400, 100), 300);
19	  });
20	
21	  it('разность не уходит ниже нуля', () => {
22	    strictEqual(subtract(100, 150), 0);
23	  });
24	
25	  it('процент округляется половиной вверх', () => {
26	    strictEqual(percent(1000, 20), 200);
27	    strictEqual(percent(105, 10), 11); // 10.5 — вверх, не отбрасывание
28	    strictEqual(percent(505, 20), 101); // 101.0 — без лишнего +1
29	  });
30	
31	  it('форматирование — разряды пробелом, копейки после запятой', () => {
32	    strictEqual(formatRub(123_456), '1 234,56 ₽');
33	  });
34	});
35

