1	/**
2	 * «Сборка» проекта.
3	 *
4	 * Компиляции здесь нет: TypeScript исполняется напрямую, типы снимает сам Node. Поэтому
5	 * сборкой считается загрузка всех модулей пакета — она ловит то, что вообще может
6	 * сломаться без компилятора: синтаксис, недостающий файл, циклический импорт, падение
7	 * на верхнем уровне модуля.
8	 *
9	 * Версия Node проверяется первой и вслух. Снятие типов включено по умолчанию начиная с
10	 * 23.6; на более старой версии импорт `.ts` падает с невнятным «Unknown file extension»,
11	 * и без этой проверки такой отказ читался бы как дефект кода.
12	 */
13	
14	import { readdirSync } from 'node:fs';
15	import { dirname, join, resolve } from 'node:path';
16	import { fileURLToPath, pathToFileURL } from 'node:url';
17	
18	const MIN_NODE = [23, 6];
19	
20	function versionProblem() {
21	  const parts = process.versions.node.split('.').map(Number);
22	  const major = parts[0] ?? 0;
23	  const minor = parts[1] ?? 0;
24	  if (major > MIN_NODE[0] || (major === MIN_NODE[0] && minor >= MIN_NODE[1])) return null;
25	  return (
26	    `нужен Node ${MIN_NODE[0]}.${MIN_NODE[1]} или новее, запущен ${process.versions.node}: ` +
27	    'на более старом снятие типов выключено и импорт .ts не работает'
28	  );
29	}
30	
31	const problem = versionProblem();
32	if (problem !== null) {
33	  console.error(`сборка невозможна: ${problem}`);
34	  process.exit(1);
35	}
36	
37	const here = dirname(fileURLToPath(import.meta.url));
38	const srcDir = resolve(here, '..', 'src');
39	
40	const modules = readdirSync(srcDir)
41	  .filter((name) => name.endsWith('.ts'))
42	  .sort();
43	
44	if (modules.length === 0) {
45	  console.error(`сборка невозможна: в ${srcDir} нет ни одного модуля`);
46	  process.exit(1);
47	}
48	
49	let failed = 0;
50	for (const name of modules) {
51	  try {
52	    await import(pathToFileURL(join(srcDir, name)).href);
53	    console.log(`ok   ${name}`);
54	  } catch (e) {
55	    failed += 1;
56	    console.error(`ОШИБКА ${name}: ${e instanceof Error ? e.message : String(e)}`);
57	  }
58	}
59	
60	console.log(`модулей загружено: ${modules.length - failed} из ${modules.length}`);
61	process.exit(failed === 0 ? 0 : 1);
